262	    public String createOwner(Owner owner, boolean sharesHousehold) throws DataAccessException {
263	        if (ownerRepository.existsByTelephone(owner.getTelephone())) {
264	            throw new DuplicateTelephoneException(owner.getTelephone());
265	        }
266	        if (owner.getEmail() != null && ownerRepository.existsByEmailIgnoreCase(owner.getEmail())) {
267	            throw new DuplicateEmailException(owner.getEmail());
268	        }
269	        List<Owner> householdMembers = findHouseholdMembers(owner);
270	        if (!householdMembers.isEmpty() && !sharesHousehold) {
271	            throw new DuplicateHouseholdException(owner.getLastName(), owner.getAddress());
272	        }
273	        long ownersInCity = ownerRepository.countByCity(owner.getCity());
274	        if (ownersInCity >= MAX_OWNERS_PER_CITY) {
275	            throw new CityCapacityExceededException(owner.getCity(), MAX_OWNERS_PER_CITY);
276	        }
277	        LocalDate effectiveDate = owner.getRegistrationDate() == null ? LocalDate.now() : owner.getRegistrationDate();
278	        owner.setRegistrationDate(BusinessDayAdjuster.toBusinessDay(effectiveDate));
279	        long ownersOnDate = ownerRepository.countByRegistrationDate(owner.getRegistrationDate());
280	        if (ownersOnDate >= MAX_OWNERS_PER_DAY) {
