216	    /**
217	     * Handles {@link DataIntegrityViolationException} which typically indicates database constraint violations. This
218	     * method returns a 404 Not Found status if an entity does not exist.
219	     *
220	     * @param e The {@link DataIntegrityViolationException} to be handled
221	     * @param request {@link HttpServletRequest} object referring to the current request.
222	     * @return A {@link ResponseEntity} containing the error information and a 404 Not Found status
223	     */
224	    @ExceptionHandler(DataIntegrityViolationException.class)
225	    @ResponseBody
226	    public ResponseEntity<ProblemDetail> handleDataIntegrityViolationException(DataIntegrityViolationException e, HttpServletRequest request) {
227	        logger.warn("Data integrity violation at {} {}: {}",
228	            request.getMethod(),
229	            request.getRequestURI(),
230	            e.getMessage());
231	        logger.debug("Data integrity violation stacktrace", e);
232	        HttpStatus status = HttpStatus.NOT_FOUND;
233	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DATA_INTEGRITY);
234	        return ResponseEntity.status(status).body(detail);
235	    }
236	
237	    /**
238	     * Handles exception thrown by Bean Validation on controller methods parameters
239	     *
240	     * @param e The {@link MethodArgumentNotValidException} to be handled
241	     * @param request {@link HttpServletRequest} object referring to the current request.
242	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
243	     */
244	    @ExceptionHandler(MethodArgumentNotValidException.class)
245	    @ResponseBody
246	    public ResponseEntity<ProblemDetail> handleMethodArgumentNotValidException(MethodArgumentNotValidException e, HttpServletRequest request) {
247	        HttpStatus status = HttpStatus.BAD_REQUEST;
248	        BindingErrorsResponse errors = new BindingErrorsResponse();
249	        BindingResult bindingResult = e.getBindingResult();
250	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
251	        detail.setProperty("errors", bindingResult.getFieldErrors().stream()
252	            .map(FieldError::getField)
253	            .distinct()
254	            .toList());
255	        if (bindingResult.hasErrors()) {
256	            errors.addAllErrors(bindingResult);
257	            List<ValidationMessageDto> schemaValidationErrors = bindingResult.getFieldErrors().stream()
258	                .map(fieldError -> {
259	                    String rejectedValue = Objects.toString(fieldError.getRejectedValue(), "null");
260	                    String defaultMessage = Objects.toString(fieldError.getDefaultMessage(), "Validation failed");
261	                    String message = "Field '%s' %s (rejected value: %s)".formatted(
262	                        fieldError.getField(),
263	                        defaultMessage,
264	                        rejectedValue);
265	                    return new ValidationMessageDto(message)
266	                        .putAdditionalProperty("field", fieldError.getField())
267	                        .putAdditionalProperty("rejectedValue", rejectedValue)
268	                        .putAdditionalProperty("defaultMessage", defaultMessage);
269	                })
270	                .toList();
271	            logger.debug("Validation error at {} {}: {}",
272	                request.getMethod(),
273	                request.getRequestURI(),
274	                bindingResult.getFieldErrors());
275	            detail.setProperty("schemaValidationErrors", schemaValidationErrors);
276	            return ResponseEntity.status(status).body(detail);
277	        }
278	        return ResponseEntity.status(status).body(detail);
279	    }
